    id: r.id,
    author: summary(r),
    body: r.body,
    imageUrl: r.media_id ? `/api/media/${r.media_id}` : null,
    createdAt: r.created_at,
    editedAt: r.edited_at,
    reactions: counts.get(r.id) ?? emptyReactions(),
    myReaction: r.my_reaction,
    commentCount: r.comment_count,
